        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    ELSIF TG_OP = 'UPDATE' THEN
        NEW.metadata = jsonb_set(NEW.metadata::jsonb, '{updated_at}', to_jsonb(NOW()));
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to set timestamps on INSERT
DROP TRIGGER IF EXISTS sms_trackers_insert_audit ON messaging.sms_trackers;
CREATE TRIGGER sms_trackers_insert_audit BEFORE INSERT ON messaging.sms_trackers
    FOR EACH ROW EXECUTE FUNCTION messaging.sms_trackers_audit_timestamp();

-- Trigger to set updated_at on UPDATE
DROP TRIGGER IF EXISTS sms_trackers_update_audit ON messaging.sms_trackers;
CREATE TRIGGER sms_trackers_update_audit BEFORE UPDATE ON messaging.sms_trackers
    FOR EACH ROW EXECUTE FUNCTION messaging.sms_trackers_audit_timestamp();

